    "folders": [
      {
        "folder_id": "drafts",
        "files": [
          {
            "file_id": "f1",
            "title": "Intro",
            "size": 10
          },
          {
            "file_id": "f2",
            "title": "Notes",
            "size": 20
          }
        ]
      },
      {
        "folder_id": "archive",
        "files": [
          {
            "file_id": "f1",
            "title": "Old intro",
            "size": 40
          }
        ]
      }
    ],
    "owner": "Ari"
  }
}

